-- Optional, owner-operated repair for untouched rows generated by the immediately
-- previous Salmon preset. This file is intentionally outside migrations and must
-- not be run automatically during deployment.
--
-- A row is eligible only when the preset id, all four totals and the saved snapshot
-- identify the old generated preset. Custom, ambiguous and edited rows remain intact.
BEGIN;

ALTER TABLE public.bulk_days DISABLE TRIGGER bulk_days_touch;

UPDATE public.bulk_days AS day
SET payload =
  day.payload
  || '{"calories":2850,"protein":120,"carbs":369,"fat":96}'::jsonb
  || jsonb_build_object(
    'mealSnapshot',
    '{"name":"SALMON DAY","base":["Milkshake","Grötbröd + cheese"],"meals":["Salmon + rice ×2","125 g raw salmon each","125 g dry Ben’s Original rice each"],"extras":["Nature Valley Oats & Honey 42 g ×1"],"macros":{"calories":2850,"protein":120,"carbs":369,"fat":96}}'::jsonb
  )
WHERE day.payload->>'mealPlan' = 'salmon'
  AND day.payload @> '{"calories":2830,"protein":118,"carbs":380,"fat":89}'::jsonb
  AND (
    NOT day.payload ? 'mealSnapshot'
    OR day.payload->'mealSnapshot' = 'null'::jsonb
    OR day.payload->'mealSnapshot' =
      '{"name":"Salmon day","base":["Milkshake","Grötbröd + cheese"],"meals":["Salmon + rice ×2","125 g salmon each","150 g dry Ben’s Original rice each"],"macros":{"calories":2830,"protein":118,"carbs":380,"fat":89}}'::jsonb
  );

ALTER TABLE public.bulk_days ENABLE TRIGGER bulk_days_touch;

COMMIT;
